import styled from '@emotion/styled';
import { Icon } from 'components/icon';
import { Card, Chip, Paragraph } from 'components/UI';
import { theme } from 'theme';
import { composeStyles } from 'utils/emotion';
import { transientShouldForwardProp } from 'utils/emotion/transientProps';

type HeaderContainerVariantProps = {
  $float?: boolean;
  $inline?: boolean;
};

type TitleVariantProps = {
  $size?: 'xxsmall' | 'small' | 'large';
};

type InlineVariantProps = {
  $inline?: boolean;
};

type ContentContainerVariantProps = InlineVariantProps & {
  $isVerticalInline?: boolean;
};

type TitleContainerVariantProps = {
  $vertical?: boolean;
};

type MeasureTextVariantProps = {
  $isVertical?: boolean;
};

type DescriptionTextVariantProps = {
  $noMargin?: boolean;
};

type ChipRootVariantProps = {
  $noMargin?: boolean;
};

export const StyledHeaderContainer = styled(Card)<HeaderContainerVariantProps>(
  composeStyles<HeaderContainerVariantProps>(
    {
      display: 'flex',
      flexDirection: 'column',
      boxShadow: '0 4px 16px -8px rgba(20, 20, 20, 0.16) !important',
      padding: '16px',
    },
    {
      $float: {
        true: {},
        false: {
          borderBottomLeftRadius: '0',
          borderBottomRightRadius: '0',
        },
      },
      $inline: {
        true: {
          backgroundColor: 'transparent !important',
          boxShadow: 'none !important',
          padding: '0',
        },
        false: {},
      },
    },
  ),
);

export const StyledTitle = styled.p<TitleVariantProps>(
  composeStyles<TitleVariantProps>(
    {
      fontWeight: '600',
      fontFamily: theme.fonts.heading,
      color: '#141414',
      margin: 0,
    },
    {
      $size: {
        large: {
          fontSize: '20px',
          lineHeight: '20px',
        },
        small: {
          fontSize: '16px',
          lineHeight: '16px',
        },
        xxsmall: {
          fontSize: '12px',
          lineHeight: '12px',
        },
      },
    },
  ),
);

export const StyledHeaderContent = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'flex-start',
  justifyContent: 'space-between',
  position: 'relative',
});

export const StyledRowContainer = styled.div<InlineVariantProps>(
  composeStyles<InlineVariantProps>(
    {
      display: 'flex',
      flexDirection: 'row',
    },
    {
      $inline: {
        true: {
          alignItems: 'baseline',
          width: '100%',
        },
        false: {
          alignItems: 'center',
        },
      },
    },
  ),
);

export const StyledContentContainer = styled.div<ContentContainerVariantProps>(
  composeStyles<ContentContainerVariantProps>(
    {
      display: 'flex',
      flexDirection: 'column',
    },
    {
      $inline: {
        true: {
          alignItems: 'center',
        },
        false: {
          alignItems: 'flex-start',
        },
      },
      $isVerticalInline: {
        true: {
          width: '100%',
        },
        false: {},
      },
    },
  ),
);

export const StyledActionsContainer = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'center',
  justifyContent: 'flex-end',
  marginLeft: '16px',
  gap: '16px',
});

export const StyledTitleContainer = styled.div<TitleContainerVariantProps>(
  composeStyles<TitleContainerVariantProps>(
    {
      display: 'flex',
      alignItems: 'center',
    },
    {
      $vertical: {
        true: {
          flexDirection: 'column',
          gap: '4px',
        },
        false: {
          flexDirection: 'row',
        },
      },
    },
  ),
);

export const MeasureText = styled(Paragraph)<MeasureTextVariantProps>(
  composeStyles<MeasureTextVariantProps>(
    {
      color: '#5C5C5C !important',
      marginLeft: '4px !important',
      whiteSpace: 'nowrap',
    },
    {
      $isVertical: {
        true: {
          margin: '4px 0',
        },
        false: {},
      },
    },
  ),
);

export const DescriptionText = styled(Paragraph)<DescriptionTextVariantProps>(
  composeStyles<DescriptionTextVariantProps>(
    {
      color: '#5C5C5C !important',
      marginTop: '8px !important',
    },
    {
      $noMargin: {
        true: {
          marginTop: '0 !important',
        },
        false: {},
      },
    },
  ),
);

export const StyledIconInfo = styled(Icon)({
  color: '#5C5C5C !important',
  marginLeft: '4px',
});

export const StyledChipRoot = styled(Chip.Root, {
  shouldForwardProp: transientShouldForwardProp,
})<ChipRootVariantProps>(
  composeStyles<ChipRootVariantProps>(
    {
      height: '14px !important',
      padding: '6px !important',
      marginTop: '8px !important',
      backgroundColor: '#FFFFFF !important',
    },
    {
      $noMargin: {
        true: {
          marginTop: '0',
        },
        false: {},
      },
    },
  ),
);

export const StyledChipLabel = styled(Chip.Label)({
  color: '#5C5C5C !important',
  fontSize: '10px !important',
});

export const StyledTopRightChipRoot = styled(Chip.Root)({
  height: '14px !important',
  padding: '6px !important',
  position: 'absolute',
  top: '0',
  right: '0',
  backgroundColor: '#FFFFFF !important',
});
